import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    if len(xs) % 2 != 0 or xs[-1] == 0:
        raise ValueError("Invalid polynomial coefficients")

    def derivative(xs, x):
        return sum([i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i > 0])

    # Try Newton's method from several starting points
    for start in [0.0, 1.0, -1.0, 2.0, -2.0, 0.5, -0.5]:
        x = start
        for _ in range(100):
            fx = poly(xs, x)
            if abs(fx) < 1e-12:
                return x
            dfx = derivative(xs, x)
            if abs(dfx) < 1e-12:
                break
            x = x - fx / dfx
        else:
            continue
        # If Newton failed, try bisection in a range around the start
        lo, hi = start - 10, start + 10
        flo = poly(xs, lo)
        fhi = poly(xs, hi)
        if flo * fhi > 0:
            continue
        for _ in range(100):
            mid = (lo + hi) / 2
            fmid = poly(xs, mid)
            if abs(fmid) < 1e-12:
                return mid
            if flo * fmid < 0:
                hi = mid
                fhi = fmid
            else:
                lo = mid
                flo = fmid
        return (lo + hi) / 2

    # Fallback: scan a wide range for sign change
    for i in range(-1000, 1001):
        x = i / 100.0
        if abs(poly(xs, x)) < 1e-12:
            return x
    raise ValueError("No zero found")

