import math

def triangle_area(a, b, c):
    if not all(isinstance(x, (int, float)) and x > 0 for x in (a, b, c)):
        return -1
    sides = sorted([a, b, c])
    if sides[0] + sides[1] <= sides[2] + 1e-9:
        return -1
    s = math.fsum(sides) / 2
    area_sq = s * (s - sides[0]) * (s - sides[1]) * (s - sides[2])
    if area_sq < 0:
        area_sq = 0
    area = math.sqrt(area_sq)
    return round(area + 1e-9, 2)

