def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # Map value to position
    pos = {}
    for i in range(n):
        for j in range(n):
            pos[grid[i][j]] = (i, j)

    # Find global minimum
    min_val = min(pos)
    start = pos[min_val]

    # BFS with state (i, j, steps, path)
    from collections import deque
    # For each position and steps, keep the best path (lexicographically smallest)
    best = {}
    q = deque()
    q.append((start[0], start[1], 1, [min_val]))
    best[(start[0], start[1], 1)] = [min_val]

    while q:
        i, j, steps, path = q.popleft()
        if steps == k:
            continue
        # Generate neighbors
        for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n:
                new_steps = steps + 1
                new_path = path + [grid[ni][nj]]
                key = (ni, nj, new_steps)
                if key not in best or new_path < best[key]:
                    best[key] = new_path
                    q.append((ni, nj, new_steps, new_path))

    # Find the best path of length k
    best_path = None
    for (i, j, steps), path in best.items():
        if steps == k:
            if best_path is None or path < best_path:
                best_path = path
    return best_path

