def do_algebra(operator, operand):
    import operator as op

    ops = {
        '+': op.add,
        '-': op.sub,
        '*': op.mul,
        '//': op.floordiv,
        '**': op.pow
    }

    # 检查输入约束
    if len(operator) != len(operand) - 1:
        raise ValueError("Operator list length must be operand list length minus one")
    if len(operand) < 2:
        raise ValueError("Operand list must have at least two elements")

    # 使用递归下降解析处理优先级
    def parse_expression(index):
        # 解析乘方（右结合）
        def parse_power(index):
            left, index = parse_factor(index)
            while index < len(operator) and operator[index] == '**':
                op_func = ops[operator[index]]
                right, index = parse_power(index + 1)
                left = op_func(left, right)
            return left, index

        # 解析乘除
        def parse_term(index):
            left, index = parse_power(index)
            while index < len(operator) and operator[index] in ('*', '//'):
                op_func = ops[operator[index]]
                right, index = parse_power(index + 1)
                left = op_func(left, right)
            return left, index

        # 解析加减
        def parse_expression_inner(index):
            left, index = parse_term(index)
            while index < len(operator) and operator[index] in ('+', '-'):
                op_func = ops[operator[index]]
                right, index = parse_term(index + 1)
                left = op_func(left, right)
            return left, index

        # 解析因子（操作数）
        def parse_factor(index):
            if index >= len(operand):
                raise IndexError("Not enough operands")
            return operand[index], index + 1

        return parse_expression_inner(index)

    result, _ = parse_expression(0)
    return result

