    step_x = b // g
    step_y = a // g

    if step_x != 0:
        k = -x0 // step_x
        if x0 + k * step_x < 0:
            k += 1
        x = x0 + k * step_x
        y = y0 - k * step_y
        if x >= 0 and y >= 0:
